import { PackageId } from "@destack/package";
import { InstallationBuild, InstallationSelection } from "../declare/installation.ts";
import { identifier, schema } from "@destack/schema";
import { SpaceDefinition } from "../declare/space.ts";
import { ResourcePlan } from "./plan.ts";

/** A build submitted to the installation following it: an application's build, or a stack's evaluated with its space definition. */
export const Submission = schema.object({
    /** The installed package. */
    packageId: PackageId,
    /** The release, repository reference or checkout the installation follows. */
    selection: InstallationSelection,
    /** The exact build evaluated. */
    build: InstallationBuild,
    /** The exported definition or parameterised function, for stacks. */
    export: schema.string().min(1).optional(),
    /** Arguments for a parameterised definition, for stacks. */
    parameters: schema.record(schema.string(), schema.json()).optional(),
    /** The evaluated space definition, for stacks. */
    definition: SpaceDefinition.optional(),
});
/** A build submitted to the installation following it. */
export type Submission = schema.Infer<typeof Submission>;

/** One change applying a stack makes to a declared record. */
export const StackChange = schema.object({
    /** Create, update or delete. */
    action: schema.enum(["create", "update", "delete"]),
    /** The declaration name. */
    name: schema.string(),
    /** Each changed field's previous and declared value, for updates. */
    fields: schema
        .record(schema.string(), schema.object({ before: schema.json(), after: schema.json() }))
        .optional(),
});

/** Whether a stack applied every declaration, or some wait for resources its controller readies. */
export const StackReason = schema.enum(["Applied", "WaitingForResources"]);
/** Whether a stack applied every declaration, or some wait for resources. */
export type StackReason = schema.Infer<typeof StackReason>;

/** The changes a stack plan or application reported for a space. */
export const StackChangeSet = schema.object({
    /** The space. */
    spaceId: identifier("space"),
    /** Whether the stack applied every declaration or waits for resources. */
    reason: StackReason,
    /** Changes by declared collection. */
    changes: schema.record(schema.string(), schema.array(StackChange)),
    /** Resource plans by resource name, for plans; applications report readiness through the resources. */
    resources: schema.record(schema.string(), ResourcePlan),
});
/** The changes a stack plan or application reported for a space. */
export type StackChangeSet = schema.Infer<typeof StackChangeSet>;
