import { check, foreignKey, sql, unique, type Select } from "@destack/db";
import { defineObject, field, method } from "@destack/object";
import { identifier } from "@destack/schema";
import { space } from "./space.ts";

/** A host authorized to execute installations in a space. */
export const spaceHost = defineObject({
    name: "space-host",
    plural: "spaceHosts",
    scope: space,
    fields: {
        /** The authorized host. */
        hostId: field.string(identifier("host")),
        /** Whether this host accepts new work or drains existing instances. */
        status: field.enum(["enabled", "draining", "disabled"]).default("enabled"),
        /** The authorization epoch used to fence revoked host credentials. */
        epoch: field.integer().default(1),
    },
    constraints: (entry) => [
        unique("space_host_scope_host").on(entry.scope, entry.hostId),
        foreignKey({ columns: [entry.scope], foreignColumns: [space.table.id] }).onDelete(
            "restrict",
        ),
        check("space_host_epoch", sql`${entry.epoch} >= 1`),
    ],
    permissions: ["read"],
    methods: {
        get: method.get("read"),
        list: method.list("read"),
        create: method.create(null, { isSystem: true }),
    },
});

/** An authorized execution host in a space. */
export type SpaceHost = Select<typeof spaceHost.table>;
