import { through } from "@destack/access";
import { check, sql, uniqueIndex, type Select } from "@destack/db";
import { defineObject, field, method } from "@destack/object";
import { PackageId } from "@destack/package";
import { defineSchema, schema } from "@destack/schema";
import { CONCURRENCIES } from "@destack/service/schedule";
import { TRIGGER_KINDS } from "@destack/service/trigger";
import { WebhookDelivery } from "@destack/service/webhook";
import { installation } from "./installation.ts";
import { space } from "./space.ts";

/** Where a run stands: waiting for an attempt, attempting, or finished one of three ways. */
export const RUN_STATES = ["pending", "running", "succeeded", "failed", "skipped"] as const;

/** Why a run failed or was skipped. */
export const RunError = defineSchema(
    schema.object({
        /** The stable failure code, such as the handler error's code. */
        code: schema.string().min(1),
        /** The failure message. */
        message: schema.string(),
    }),
);
/** Why a run failed or was skipped. */
export type RunError = schema.Infer<typeof RunError>;

/** One delivery of a trigger's cause to an installation's workload. */
export const run = defineObject({
    name: "run",
    plural: "runs",
    scope: space,
    fields: {
        /** The installation whose workload runs. */
        installation: field.reference(installation, { delete: "cascade" }),

        // the trigger: its kind and its declaration, named within the declaring package
        /** The kind of trigger delivered. */
        kind: field.enum(TRIGGER_KINDS),
        /** The package declaring the trigger. */
        packageId: field.string(PackageId),
        /** The trigger's name within its package. */
        trigger: field.string(schema.string().min(1)),

        // the cause, by trigger kind
        /** The occurrence a schedule delivers. */
        scheduledAt: field.time().optional(),
        /** The webhook delivery. */
        deliveryId: field.string(schema.string().min(1)).optional(),
        /** The webhook delivery's event and body. */
        delivery: field.json(WebhookDelivery.omit({ id: true })).optional(),
        /** The log epoch of a watch's change. */
        epoch: field.string(schema.string().min(1)).optional(),
        /** The log sequence of a watch's change. */
        sequence: field.integer().optional(),
        /** The row a snapshot delivers at one log position. */
        key: field.string(schema.string().min(1)).optional(),

        // the execution
        /** Where the run stands. */
        state: field.enum(RUN_STATES),
        /** Whether runs of the trigger may overlap. */
        concurrency: field.enum(CONCURRENCIES),
        /** The attempts started so far. */
        attempts: field.integer(),
        /** The first attempt's start, in UTC epoch milliseconds. */
        startedAt: field.time().optional(),
        /** The finish, in UTC epoch milliseconds. */
        finishedAt: field.time().optional(),
        /** Why the run failed or was skipped. */
        error: field.json(RunError).optional(),
        /** The trace of the run's attempts. */
        traceId: field.string(schema.string().min(1)).optional(),
    },
    constraints: (run) => [
        // run each cause once per trigger
        uniqueIndex("run_schedule_cause")
            .on(run.installation, run.packageId, run.trigger, run.scheduledAt)
            .where(sql`${run.kind} = 'schedule'`),
        uniqueIndex("run_webhook_cause")
            .on(run.installation, run.packageId, run.trigger, run.deliveryId)
            .where(sql`${run.kind} = 'webhook'`),
        uniqueIndex("run_watch_cause")
            .on(run.installation, run.packageId, run.trigger, run.epoch, run.sequence)
            .where(sql`${run.kind} = 'watch' AND ${run.key} IS NULL`),
        uniqueIndex("run_snapshot_cause")
            .on(run.installation, run.packageId, run.trigger, run.epoch, run.sequence, run.key)
            .where(sql`${run.kind} = 'watch' AND ${run.key} IS NOT NULL`),

        // claim a trigger that refuses overlapping runs for one run at a time, across hosts
        uniqueIndex("run_claim")
            .on(run.installation, run.kind, run.packageId, run.trigger)
            .where(sql`${run.state} IN ('pending', 'running') AND ${run.concurrency} <> 'allow'`),

        // hold exactly the cause of the run's trigger kind
        check(
            "run_cause",
            sql`(${run.kind} = 'schedule' AND ${run.scheduledAt} IS NOT NULL AND ${run.deliveryId} IS NULL AND ${run.delivery} IS NULL AND ${run.epoch} IS NULL AND ${run.sequence} IS NULL AND ${run.key} IS NULL) OR (${run.kind} = 'webhook' AND ${run.deliveryId} IS NOT NULL AND ${run.delivery} IS NOT NULL AND ${run.scheduledAt} IS NULL AND ${run.epoch} IS NULL AND ${run.sequence} IS NULL AND ${run.key} IS NULL) OR (${run.kind} = 'watch' AND ${run.epoch} IS NOT NULL AND ${run.sequence} IS NOT NULL AND ${run.scheduledAt} IS NULL AND ${run.deliveryId} IS NULL AND ${run.delivery} IS NULL)`,
        ),
        check("run_attempts", sql`${run.attempts} >= 0`),
        check(
            "run_finish",
            sql`(${run.state} IN ('succeeded', 'failed', 'skipped')) = (${run.finishedAt} IS NOT NULL)`,
        ),
    ],
    permissions: { read: through("installation", "read") },
    methods: {
        get: method.get("read"),
        list: method.list("read"),
        create: method.create(null, { isSystem: true }),
        update: method.update(null, { isSystem: true }),
    },
});

/** One recorded run of a trigger. */
export type Run = Select<typeof run.table>;
