import { Risk } from "@destack/resource";
import { schema } from "@destack/schema";

/** The steps a resource's plan makes, as reviewers see them. */
export const ResourcePlan = schema.object({
    /** The digest an approval names. */
    digest: schema.string(),
    /** The most consequential step's risk. */
    risk: Risk,
    /** The steps in application order. */
    steps: schema.array(
        schema.object({
            /** What the step changes, such as addColumn. */
            kind: schema.string(),
            /** How consequential the step is. */
            risk: Risk,
            /** The changed part of the resource, such as a table. */
            target: schema.string(),
            /** A readable summary. */
            detail: schema.string(),
        }),
    ),
});
/** The steps a resource's plan makes, as reviewers see them. */
export type ResourcePlan = schema.Infer<typeof ResourcePlan>;

/** The desired states a resource applied, and the plan waiting to apply them. */
export const ResourceStatus = schema.object({
    /** The applied desired states, with the plan waiting for approval or blocked until applied. */
    state: schema
        .object({
            /** The digest of the bound desired states. */
            digest: schema.string(),
            /** The plan waiting to apply them, absent once applied. */
            plan: ResourcePlan.optional(),
        })
        .optional(),
});
/** The desired states a resource applied, and the plan waiting to apply them. */
export type ResourceStatus = schema.Infer<typeof ResourceStatus>;
