import { LogPosition } from "@destack/db/log";
import { schema } from "@destack/schema";
import { defineProcedure, eventIterator } from "@destack/service";
import { QueryPage, ObjectTypeReference } from "@destack/sync";
import { installation } from "../object/installation.ts";
import { InstallationKey } from "./key.ts";

/** The access to a space's objects that each installation's database copies. */
export const access = {
    /** Follow the access of the space or a containing scope from a position, or from a snapshot without one. */
    watch: defineProcedure({
        authentication: "identity",
        permission: installation.permission("replicate"),
        audit: false,
    })
        .route({ method: "POST", path: "/spaces/{spaceId}/installations/{installationId}/access" })
        .input(
            InstallationKey.extend({
                /** The scope with the access to follow: the space or a containing scope. */
                scope: schema.string().min(1),
                /** The object types the installation's database holds the access rows of itself. */
                held: schema.array(ObjectTypeReference),
                /** The object types whose inherited rows the installation's database copies. */
                copied: schema.array(ObjectTypeReference),
                /** The log position the follower holds, absent before its first snapshot. */
                after: LogPosition.optional(),
            }),
        )
        .output(eventIterator(QueryPage)),
};
