import { check, index, sql, unique, type Select } from "@destack/db";
import { defineObject, field, method } from "@destack/object";
import { identifier } from "@destack/schema";
import { space } from "./space.ts";

/** A read-only copy of the public profile of a user the space's access names. */
export const member = defineObject({
    name: "member",
    plural: "members",
    scope: space,
    fields: {
        /** The member. */
        userId: field.string(identifier("user")),
        /** The member's display name. */
        name: field.string(),
        /** The member's profile image URL, absent without one. */
        image: field.string().optional(),
        /** The member's personal account and handle, absent before the user has one. */
        accountId: field.string(identifier("account")).optional(),
        /** The member's handle, their personal account's. */
        handle: field.string().optional(),
        /** The snapshot of the space's copy that last delivered the member. */
        snapshot: field.integer().default(0),
    },
    constraints: (entry) => [
        unique("member_user").on(entry.scope, entry.userId),
        index("member_snapshot").on(entry.scope, entry.snapshot),
        check("member_handle", sql`(${entry.accountId} IS NULL) = (${entry.handle} IS NULL)`),
    ],
    permissions: ["read"],
    methods: {
        get: method.get("read"),
        list: method.list("read"),
        create: method.create(null, { isSystem: true }),
        update: method.update(null, { isSystem: true }),
        delete: method.delete(null, { isSystem: true }),
    },
});

/** A space member's public profile. */
export type Member = Select<typeof member.table>;
